ALTER TABLE "AdminUser" ADD COLUMN "gender" TEXT, ADD COLUMN "avatarUrl" TEXT, ADD COLUMN "verified" BOOLEAN NOT NULL DEFAULT true, ADD COLUMN "twoFactorEnabled" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "twoFactorMethod" TEXT;
CREATE TABLE "AdminTwoFactorCode" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"codeHash" TEXT NOT NULL,"method" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"attempts" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AdminTwoFactorCode_pkey" PRIMARY KEY ("id"),CONSTRAINT "AdminTwoFactorCode_userId_fkey" FOREIGN KEY ("userId") REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "AdminTwoFactorCode_userId_createdAt_idx" ON "AdminTwoFactorCode"("userId","createdAt");
CREATE TABLE "AdminNotification" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"imageUrl" TEXT,"linkUrl" TEXT,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AdminNotification_pkey" PRIMARY KEY ("id"),CONSTRAINT "AdminNotification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "AdminNotification_userId_readAt_createdAt_idx" ON "AdminNotification"("userId","readAt","createdAt");
